import{_ as n,C as i,o as r,c as s,ah as e,E as o}from"./chunks/framework.sPHStHqt.js";const m=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"settings/configuration.md","filePath":"settings/configuration.md","lastUpdated":1789630599000}'),l={name:"settings/configuration.md"};function g(p,t,h,c,u,d){const a=i("ImagePopup");return r(),s("div",null,[t[0]||(t[0]=e('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Configuration is where the platform&#39;s global settings live — your logo, the default language, the Stripe connection that takes payment, and the free-trial rules. Get these right once and the rest of the platform works.</p><div class="info custom-block"><p class="custom-block-title">What you&#39;ll learn</p><ul><li>Where configuration lives and how it&#39;s organised</li><li>How to set your logo and locale</li><li>How to connect Stripe so paid plans work</li><li>Where the notification and trial settings are</li></ul></div><h2 id="finding-it" tabindex="-1">Finding it <a class="header-anchor" href="#finding-it" aria-label="Permalink to &quot;Finding it&quot;">​</a></h2><p>Open <strong>Configuration</strong> in the sidebar. Settings are grouped into two areas — <strong>General</strong> and <strong>Subscription</strong> — and you save each group on its own with <strong>Save Configuration</strong>.</p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><p>The <strong>General</strong> group covers how the platform looks and what language it speaks.</p>',7)),o(a,{src:"/images/configuration/config-general.png",alt:"General configuration — logo and locale"}),t[1]||(t[1]=e('<ul><li><strong>Logo</strong> — upload the image shown in the super-admin panel. Accepts JPG, PNG, WEBP, SVG and BMP.</li><li><strong>Locale Settings</strong> — the default language, <strong>English</strong> out of the box.</li></ul><h2 id="subscription" tabindex="-1">Subscription <a class="header-anchor" href="#subscription" aria-label="Permalink to &quot;Subscription&quot;">​</a></h2><p>The <strong>Subscription</strong> group holds everything about billing and sign-ups. It has three blocks.</p><h3 id="notification-email" tabindex="-1">Notification email <a class="header-anchor" href="#notification-email" aria-label="Permalink to &quot;Notification email&quot;">​</a></h3><p>Choose where the platform sends its tenant notifications.</p><ul><li><strong>Super Admin Notification Email</strong> — turn on to receive all tenant notifications at a super-admin address.</li><li><strong>Notification Email Addresses</strong> — the address or addresses to send to. Enter several separated by commas, e.g. <code>admin@example.com, support@example.com</code>.</li></ul><h3 id="stripe" tabindex="-1">Stripe <a class="header-anchor" href="#stripe" aria-label="Permalink to &quot;Stripe&quot;">​</a></h3><p>This is the connection that lets tenants pay for plans. Without it, paid plans can&#39;t be purchased.</p>',8)),o(a,{src:"/images/configuration/config-stripe.png",alt:"Stripe configuration"}),t[2]||(t[2]=e('<ul><li><strong>Status</strong> — turn on to enable Stripe payments.</li><li><strong>Stripe Publishable Key</strong> <em>(required)</em> — from your Stripe dashboard.</li><li><strong>Stripe Secret Key</strong> <em>(required)</em> — from your Stripe dashboard. Kept hidden once saved.</li><li><strong>Stripe Webhook Secret</strong> — the signing secret for Stripe&#39;s webhook, so Krayin can confirm payments.</li><li><strong>Mode</strong> — <strong>Sandbox</strong> for testing with Stripe&#39;s test keys, or <strong>Live</strong> to take real payments. Match this to the type of keys you entered.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Use <strong>Sandbox</strong> with test keys while you set things up, and switch to <strong>Live</strong> only when you enter your live keys. Running live mode with test keys — or the reverse — means no payment will go through.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>When you create or edit a priced <a href="/subscriptions/plan-management">plan</a>, Krayin registers it with Stripe using these keys. So connect Stripe <strong>before</strong> you publish paid plans.</p></div><p>Once Stripe is connected, a tenant who picks a paid plan is sent to <strong>Stripe&#39;s hosted checkout</strong> to enter their card — the platform never sees or stores card details. Stripe then calls back to confirm the payment (that&#39;s what the <strong>Webhook Secret</strong> verifies), the tenant&#39;s account is activated, and an invoice is raised. You can see that flow from the tenant&#39;s side on <a href="/tenants/registration">Registration → Paying for a paid plan</a>.</p><h3 id="free-trial" tabindex="-1">Free Trial <a class="header-anchor" href="#free-trial" aria-label="Permalink to &quot;Free Trial&quot;">​</a></h3><p>Whether new tenants can start on a free trial, and for how long.</p>',6)),o(a,{src:"/images/configuration/config-trial.png",alt:"Free Trial configuration"}),t[3]||(t[3]=e('<ul><li><strong>Status</strong> — turn on to offer trials. Requires an active plan marked as the trial plan.</li><li><strong>Trial Period (Days)</strong> — how long a trial runs. Accepts 1–365, defaults to 14.</li></ul><p>This block is explained in full on <a href="/subscriptions/trials">Free Trials</a>.</p><h2 id="where-to-go-next" tabindex="-1">Where to go next <a class="header-anchor" href="#where-to-go-next" aria-label="Permalink to &quot;Where to go next&quot;">​</a></h2><ul><li>Set up the trial plan these settings govern → <a href="/subscriptions/trials">Free Trials</a></li><li>Build the paid plans Stripe will charge for → <a href="/subscriptions/plan-management">Plan Management</a></li><li>Add colleagues to help you run the platform → <a href="/settings/agents-and-roles">Agents &amp; Roles</a></li></ul>',4))])}const b=n(l,[["render",g]]);export{m as __pageData,b as default};
